export const postsForLang = (lang) => { const f = BLOG_POSTS.filter(p => p.lang === lang); return f.length ? f : BLOG_POSTS.filter(p => p.lang === 'en'); };
export const findPost = (slug, lang) => BLOG_POSTS.find(p => p.slug === slug && p.lang === lang) || BLOG_POSTS.find(p => p.slug === slug) || null;
